/** @param {number} value */
export function linear(value: number) { return value; }
/** @param {number} value */
export function quadIn(value: number) { return value * value; }
/** @param {number} value */
export function quadOut(value: number) { return value * (2 - value); }
/** @param {number} value */
export function quadInOut(value: number) { return value < 0.5 ? 2 * value * value : -1 + (4 - 2 * value) * value; }
/** @param {number} value */
export function cubicIn(value: number) { return value * value * value; }
/** @param {number} value */
export function cubicOut(value: number) { return 1 + (--value) * value * value; }
/** @param {number} value */
